DELETE:
DELETE FROM users WHERE status = 'deleted' AND created_at < '2020-01-01';

-- Delete with join (remove orphaned records)
DELETE o FROM orders o
  LEFT JOIN users u ON o.user_id = u.id
  WHERE u.id IS NULL;

-- Safe delete: check first
SELECT COUNT(*) FROM users WHERE status = 'banned';
DELETE FROM users WHERE status = 'banned';

