JSON in MySQL:
CREATE TABLE events (
  id INT AUTO_INCREMENT PRIMARY KEY,
  data JSON
);

INSERT INTO events (data) VALUES
  ('{"type": "click", "page": "/home", "userId": 42}'),
  ('{"type": "purchase", "total": 29.99, "items": ["book", "pen"]}');

SELECT data->>'$.type' AS event_type FROM events;
SELECT * FROM events WHERE JSON_CONTAINS(data->>'$.type', '"click"');

-- Generated column index for JSON field
ALTER TABLE events ADD COLUMN event_type VARCHAR(50) GENERATED ALWAYS AS (data->>'$.type') STORED;
CREATE INDEX idx_event_type ON events(event_type);

