Views:
CREATE VIEW active_customers AS
SELECT u.id, u.name, COUNT(o.id) AS order_count, SUM(o.total) AS total_spent
FROM users u
LEFT JOIN orders o ON u.id = o.user_id
WHERE u.status = 'active'
GROUP BY u.id, u.name;

SELECT * FROM active_customers WHERE total_spent > 500;

-- Updatable view with WITH CHECK OPTION
CREATE VIEW active_users AS
SELECT id, name, email, status
FROM users
WHERE status = 'active'
WITH CHECK OPTION;

-- This INSERT works (matches the condition)
INSERT INTO active_users (name, email, status) VALUES ('Alice', 'alice@test.com', 'active');

-- This INSERT fails (status would make row disappear from view)
INSERT INTO active_users (name, email, status) VALUES ('Bob', 'bob@test.com', 'inactive');
-- ERROR: CHECK OPTION failed

DROP VIEW IF EXISTS active_customers;

Indexing Strategies:
-- BTREE index (default)
CREATE INDEX idx_email ON users(email);

-- Composite index (leftmost prefix matters)
CREATE INDEX idx_state_city_zip ON addresses(state, city, zip);
-- Helps: WHERE state='CA'
-- Helps: WHERE state='CA' AND city='SF'
-- Helps: WHERE state='CA' AND city='SF' AND zip='94105'
-- Does NOT help: WHERE city='SF' (missing leading column)

-- HASH index (MEMORY engine only)
CREATE INDEX idx_hash_email ON users(email) USING HASH;

-- EXPLAIN to verify
EXPLAIN SELECT * FROM users WHERE email = 'test@example.com';
-- Look for: possible_keys, key, type (const/ref = good, ALL = bad), rows

-- Covering index (includes all needed columns)
CREATE INDEX idx_covering ON orders(user_id, status, total);
EXPLAIN SELECT user_id, status, total FROM orders WHERE user_id = 42;
-- Extra: Using index (means fully covered, no table lookup needed)

-- Drop unused indexes
SHOW INDEX FROM users;
DROP INDEX idx_unused ON users;

Transactions & Isolation:
START TRANSACTION;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

-- Rollback on error
START TRANSACTION;
UPDATE inventory SET stock = stock - 1 WHERE product_id = 10;
UPDATE orders SET status = 'confirmed' WHERE id = 100;
-- If something goes wrong:
ROLLBACK;

-- Savepoints
START TRANSACTION;
INSERT INTO audit_log SET action = 'start';
SAVEPOINT sp1;
UPDATE products SET price = price * 1.1 WHERE category = 'Electronics';
ROLLBACK TO SAVEPOINT sp1; -- undo the price update
COMMIT; -- only the audit log insert is saved

-- Check/set isolation level
SELECT @@transaction_isolation;
SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;
SET GLOBAL TRANSACTION ISOLATION LEVEL REPEATABLE READ;

User Management:
CREATE USER 'app_user'@'localhost' IDENTIFIED BY 'strong_password_123';
CREATE USER 'readonly'@'%' IDENTIFIED BY 'readonly_pass';

-- Grant specific privileges
GRANT SELECT, INSERT, UPDATE ON mydb.* TO 'app_user'@'localhost';
GRANT SELECT ON mydb.* TO 'readonly'@'%';

-- Grant all privileges on a database
GRANT ALL PRIVILEGES ON mydb.* TO 'admin'@'localhost';

-- Grant with grant option (can grant to others)
GRANT ALL PRIVILEGES ON *.* TO 'superadmin'@'localhost' WITH GRANT OPTION;

-- Revoke privileges
REVOKE DELETE ON mydb.* FROM 'app_user'@'localhost';

-- Flush privileges (needed if modifying grant tables directly)
FLUSH PRIVILEGES;

-- Show user privileges
SHOW GRANTS FOR 'app_user'@'localhost';

-- Drop user
DROP USER IF EXISTS 'old_user'@'localhost';

-- Change password
ALTER USER 'app_user'@'localhost' IDENTIFIED BY 'new_strong_password';
